MIN = r"Сколько минут в $\dfrac{%d}{%d}$ ч?"
def minh(n, d):
    k = 60 * n // d
    return P(MIN % (n, d), r"$%d$ мин" % k, [(r"$%s$ мин" % num(D(100 * n) / D(d)), r"Ученик считал, что в часе $100$ минут."), (r"$%s$ мин" % num(D(60) / D(d)), r"Ученик нашёл только $\dfrac{1}{%d}$ часа, не умножив на числитель $%d$." % (d, n)) if n > 1 else (r"$%d$ мин" % (60 * d), r"Ученик умножил на знаменатель вместо деления."), (r"$%s$ мин" % num(D(60 * d) / D(n)), r"Ученик перевернул дробь.") if n > 1 else (r"$%s$ мин" % num(D(n) / D(d)), r"Ученик записал долю часа как число минут, не умножив на $60$.")])
